// Trivial CUDA kernel used only to test whether nvcc 13.3 accepts the
// installed MSVC 19.44 (toolset 14.44) host compiler. Not a product artifact.
#include <cstdio>
#include <cuda_runtime.h>

__global__ void vectorAdd(const float* a, const float* b, float* c, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) c[i] = a[i] + b[i];
}

int main() {
    const int n = 1024;
    const size_t bytes = n * sizeof(float);

    float* h_a = (float*)malloc(bytes);
    float* h_b = (float*)malloc(bytes);
    float* h_c = (float*)malloc(bytes);
    if (!h_a || !h_b || !h_c) { printf("host alloc failed\n"); return 2; }
    for (int i = 0; i < n; ++i) { h_a[i] = 1.0f; h_b[i] = 2.0f; h_c[i] = 0.0f; }

    int device = 0;
    cudaError_t err = cudaGetDevice(&device);
    if (err != cudaSuccess) { printf("cudaGetDevice failed: %s\n", cudaGetErrorString(err)); return 3; }
    cudaDeviceProp prop;
    err = cudaGetDeviceProperties(&prop, device);
    if (err != cudaSuccess) { printf("cudaGetDeviceProperties failed: %s\n", cudaGetErrorString(err)); return 3; }
    printf("device=%d name=%s cc=%d.%d\n", device, prop.name, prop.major, prop.minor);

    float *d_a, *d_b, *d_c;
    err = cudaMalloc(&d_a, bytes); if (err != cudaSuccess) { printf("cudaMalloc d_a: %s\n", cudaGetErrorString(err)); return 4; }
    err = cudaMalloc(&d_b, bytes); if (err != cudaSuccess) { printf("cudaMalloc d_b: %s\n", cudaGetErrorString(err)); return 4; }
    err = cudaMalloc(&d_c, bytes); if (err != cudaSuccess) { printf("cudaMalloc d_c: %s\n", cudaGetErrorString(err)); return 4; }

    cudaMemcpy(d_a, h_a, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(d_b, h_b, bytes, cudaMemcpyHostToDevice);

    const int threads = 256;
    const int blocks = (n + threads - 1) / threads;
    vectorAdd<<<blocks, threads>>>(d_a, d_b, d_c, n);

    err = cudaDeviceSynchronize();
    if (err != cudaSuccess) { printf("kernel failed: %s\n", cudaGetErrorString(err)); return 5; }

    cudaMemcpy(h_c, d_c, bytes, cudaMemcpyDeviceToHost);
    int bad = 0;
    for (int i = 0; i < n; ++i) if (h_c[i] != 3.0f) ++bad;
    printf("n=%d expected=3.0 mismatches=%d first=%.1f\n", n, bad, h_c[0]);

    cudaFree(d_a); cudaFree(d_b); cudaFree(d_c);
    free(h_a); free(h_b); free(h_c);
    return bad == 0 ? 0 : 1;
}
